Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
(* [comment removed for export] *)
Ltac accok_fp_on ::= fail.

(* [comment removed for export] *)
Definition CNT_STOPS : list Z := [e_stack_malloc 0%nat; e_returnErrorInt; e_calloc; e_free; cnt_msg; cnt_fh; cnt_fl].

(* [comment removed for export] *)
Definition A_MSG_COUNT : Z := 0x3a360.
Definition A_PROC_COUNT : Z := 0x3a340.

(* [comment removed for export] *)
Ltac shbr_ld :=
  lazymatch goal with
  | |- evt ?segs ?Q (MS ?R ?F (if ?c then Z_to_bv 64 ?SLOW else Z_to_bv 64 ?FAST) ?fc ?rv ?m ?ro) =>
      let b := shbyte_of c in
      lazymatch goal with
      | K : shk m b ?X |- _ =>
          let S4 := eval vm_compute in (SLOW + 4)%Z in
          let S8 := eval vm_compute in (SLOW + 8)%Z in
          instr_at segs S4 ltac:(fun i =>
            lazymatch i with
            | OpImm ALU_AND ?ru _ _ =>
                instr_at segs S8 ltac:(fun i2 =>
                  let szm1 := lazymatch i2 with
                              | OpImm ALU_ADD _ _ ?imm => eval vm_compute in (bv_unsigned imm)
                              | _ => constr:(0%Z) end in
                  let sz := eval vm_compute in (szm1 + 1)%Z in
                  let OK := fresh "SHOK" in
                  first [
                    match goal with
                    | ACC : acc asegs m ?a ?n |- _ =>
                        assert (OK : sh_ok b (X + sz - 1)) by (apply (shk_ok m a n X sz b ACC K); lia)
                    end
                  | fail 1 "shbr_ld: cannot prove the access addressable:" X sz ];
                  let BB := fresh "BB" in
                  assert (BB : 0 <= bv_unsigned b < 8) by (pose proof (bv_unsigned_in_range 8 b); destruct OK as [?|[? ?]]; lia);
                  rewrite ?(sxb_small b) by lia;
                  shbr_merge ru FAST OK; clear K BB)
            end)
      end
  end.

Section COUNTC.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Hypothesis RERR : returnError_cpsF RT e_returnErrorInt.
Hypothesis LIT1 : exists l, In (A_MSG_COUNT, l) LEPT_LITS.
Hypothesis LIT2 : exists l, In (A_PROC_COUNT, l) LEPT_LITS.

Lemma count_c0 : pixCountPixels2_case RT 0.
Proof using AF GP FKC RERR LIT1 LIT2.
ltac2:(KReplay.run1 (kr_t_Po_count_c0 ()) ["COUNTC"] (String.concat "" [kr_b_Po_count_c0_1_1 (); kr_b_Po_count_c0_1_2 ()])). Qed.
End COUNTC.
